using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed partial class StateQ {public string Safety{get;set;}="Green";public Dictionary<string,LegalActorQ> Legal{get;set;}=[];public List<DuelQ> Duels{get;set;}=[];public List<KillRightQ> KillRights{get;set;}=[];public DateTime PoliceDue{get;set;}public string PoliceState{get;set;}="Idle";}
public sealed class LegalActorQ {public DateTime Weapons{get;set;}public DateTime Pvp{get;set;}public DateTime Npc{get;set;}public DateTime Suspect{get;set;}public DateTime Criminal{get;set;}public Dictionary<string,DateTime> Engagements{get;set;}=[];}
public sealed class DuelQ {public string A{get;set;}="";public string B{get;set;}="";public string State{get;set;}="Offered";public DateTime Expires{get;set;}}
public sealed class KillRightQ {public string Owner{get;set;}="";public string Target{get;set;}="";public DateTime Expires{get;set;}public bool Used{get;set;}}
public sealed partial class PilotC {public bool CapsuleerQ{get;set;}}
public sealed partial class DemoWorld {
 public LegalActorQ LawQ(string actor="player"){if(!SystemsQ.Legal.TryGetValue(actor,out var law))SystemsQ.Legal[actor]=law=new();return law;}
 public string SetSafetyQ(string level){if(level is not("Green" or "Yellow" or "Red"))return "Choose Green, Yellow or Red safety.";SystemsQ.Safety=level;WeaponSafety=level=="Green";return "";}
 string CorpOfQ(string actor)=>actor.StartsWith("structure-q:")?Organisations.Structures.FirstOrDefault(s=>"structure-q:"+s.Id==actor)?.Corp??"":actor=="player"?Organisations.PlayerCorp:Organisations.Corps.FirstOrDefault(c=>c.Members.ContainsKey(actor))?.Id??(PopulationPilot(actor) is {} p?"npc:"+p.Company:"");
 public bool WarLegalQ(string a,string b){string ca=CorpOfQ(a),cb=CorpOfQ(b);return ca!=""&&cb!=""&&Organisations.Wars.Any(w=>w.Starts<=Now&&w.Ends>Now&&(w.A==ca&&w.B==cb||w.A==cb&&w.B==ca));}
 public bool LegalAttackQ(string source,SpaceTarget target,bool apply=true){if(WeaponTestMode||source!="player"&&!Population.Pilots.Any(p=>p.Id==source&&p.CapsuleerQ))return true;bool capsuleer=PopulationPilot(target.Id)?.CapsuleerQ==true||target.Id.StartsWith("structure-q:");if(!capsuleer){if(apply)LawQ(source).Npc=Now.AddMinutes(5);return true;}var src=LawQ(source);var victim=LawQ(target.Id);bool permitted=Current.Security<=0||!target.Friendly&&PopulationPilot(target.Id)?.Role=="Pirate"||victim.Suspect>Now||victim.Criminal>Now||src.Engagements.GetValueOrDefault(target.Id)>Now||WarLegalQ(source,target.Id)||target.OwnerId==source&&PopulationPilot(target.Id)==null||target.OwnerId==CorpOfQ(source)&&target.OwnerId!="";
  bool criminal=!permitted&&Current.Security>=.5;bool suspect=!permitted&&Current.Security>0&&!criminal;string safety=source=="player"?(WeaponSafety?"Green":SystemsQ.Safety=="Green"?"Red":SystemsQ.Safety):"Red";if(criminal&&safety!="Red"||suspect&&safety=="Green"){if(source=="player")Say("Safety blocks illegal aggression.");return false;}if(!apply)return true;src.Weapons=Now.AddSeconds(60);src.Pvp=Now.AddMinutes(15);victim.Pvp=Now.AddMinutes(15);src.Engagements[target.Id]=Now.AddMinutes(5);victim.Engagements[source]=Now.AddMinutes(5);if(criminal){src.Criminal=Now.AddMinutes(15);src.Suspect=default;SystemsQ.KillRights.Add(new(){Owner=target.Id,Target=source,Expires=Now.AddDays(30)});if(source=="player"){SystemsQ.PoliceDue=Now.AddSeconds(6);SystemsQ.PoliceState="Responding";Organisations.CriminalUntil=src.Criminal;}}else if(suspect){if(src.Criminal>Now)src.Criminal=Now.AddMinutes(15);else src.Suspect=Now.AddMinutes(15);if(source=="player")Organisations.SuspectUntil=src.Suspect;}return true;
 }
 public bool LegalTheftQ(string owner){if(owner is "" or "player" or "unclaimed" or "abandoned"||owner==Organisations.PlayerCorp&&owner!=""||Current.Security<=0)return true;string safety=WeaponSafety?"Green":SystemsQ.Safety=="Green"?"Red":SystemsQ.Safety;if(safety=="Green")return false;var law=LawQ();if(law.Criminal>Now)law.Criminal=Now.AddMinutes(15);else law.Suspect=Now.AddMinutes(15);Organisations.SuspectUntil=law.Suspect;return true;}
 public bool LegalAssistQ(string actor,string recipient,bool apply=true){if(WeaponTestMode)return true;var t=LawQ(recipient);bool criminal=Current.Security>=.5&&(t.Criminal>Now||t.Suspect>Now||t.Engagements.Values.Any(e=>e>Now))||Current.Security>0&&t.Criminal>Now;if(criminal&&actor=="player"&&(WeaponSafety||SystemsQ.Safety!="Red"))return false;if(!apply)return true;var a=LawQ(actor);if(t.Weapons>a.Weapons)a.Weapons=t.Weapons;if(t.Pvp>a.Pvp)a.Pvp=t.Pvp;if(criminal){a.Criminal=Now.AddMinutes(15);if(actor=="player"&&Current.Security>=.5){SystemsQ.PoliceDue=Now.AddSeconds(6);SystemsQ.PoliceState="Responding";}}return true;}
 public string OfferDuelQ(string id){if(PopulationPilot(id) is not {Fit.Hull:>0} p||id=="player"||!Targets.Any(t=>t.Id==id&&t.Alive)||SystemsQ.Duels.Any(d=>d.A=="player"&&d.B==id&&d.State=="Offered"&&d.Expires>Now))return "Observe a living local pilot and avoid duplicate invitations.";p.CapsuleerQ=true;SystemsQ.Duels.Add(new(){A="player",B=id,Expires=Now.AddMinutes(5)});return "";}
 public string ResolveDuelQ(string id,bool accept){var d=SystemsQ.Duels.LastOrDefault(d=>d.B==id&&d.A=="player"&&d.State=="Offered"&&d.Expires>Now);if(d==null)return "No live local duel invitation.";d.State=accept?"Accepted":"Declined";if(accept){LawQ().Engagements[id]=Now.AddMinutes(5);LawQ(id).Engagements["player"]=Now.AddMinutes(5);}return "";}
 public string ActivateKillRightQ(string owner,string target){var k=SystemsQ.KillRights.FirstOrDefault(k=>k.Owner==owner&&k.Target==target&&!k.Used&&k.Expires>Now);if(k==null||owner!="player"&&!Organisations.Corps.Any(c=>c.Id==Organisations.PlayerCorp&&c.Members.ContainsKey(owner)))return "Owned live kill right required.";k.Used=true;LawQ(target).Suspect=Now.AddMinutes(15);return "";}
 public bool TravelInterlockQ(bool gate=false){var law=LawQ();if(law.Criminal>Now&&Current.Security>=.5){Say("Criminal timer prevents high-security travel.");return false;}if(gate&&law.Weapons>Now){Say("Weapons timer prevents docking and gate use.");return false;}return true;}
 public void TickLegalQ(double seconds){var law=LawQ();foreach(var a in SystemsQ.Legal.Values)foreach(string id in a.Engagements.Where(e=>e.Value<=Now).Select(e=>e.Key).ToArray())a.Engagements.Remove(id);foreach(var d in SystemsQ.Duels.Where(d=>d.State=="Offered"&&d.Expires<=Now))d.State="Expired";
  if(law.Criminal<=Now){SystemsQ.PoliceState="Idle";return;}if(Current.Security>=.5&&!Docked&&SystemsQ.PoliceState=="Responding"&&SystemsQ.PoliceDue<=Now){for(int i=0;i<3;i++){string id="police-q:"+i;if(Targets.Any(t=>t.Id==id))continue;var t=MakeRaider(Player.Position+new Vector3(3000+i*500,0,600));t.Id=id;t.Name="Concord of Worlds response";t.Friendly=false;t.Training=true;t.LockId="player";t.Profile!.SetStat("maxTargetRange",100000);Targets.Add(t);}SystemsQ.PoliceState="On grid";}if(SystemsQ.PoliceState=="On grid"&&seconds>0&&Current.Security>=.5&&!Docked){Player.DriveLockout=Math.Max(Player.DriveLockout,2);DealPlayerDamage((float)Math.Min(500,seconds*100),DamageType.EM);}
 }
}
